def check_character_frequency(S: str) -> str:
    frequency_count = {}
    for char in S:
        if char in frequency_count:
            frequency_count[char] += 1
        else:
            frequency_count[char] = 1

    frequency_occurrences = {}
    for frequency in frequency_count.values():
        if frequency in frequency_occurrences:
            frequency_occurrences[frequency] += 1
        else:
            frequency_occurrences[frequency] = 1

    for count in frequency_occurrences.values():
        if count != 0 and count != 2:
            return "No"

    return "Yes"
